// Builds tokens.css and tokens.ts from tokens.json, and checks WCAG contrast for every declared pair in every theme.
//
//   node scripts/build-tokens.mjs           write the generated files
//   node scripts/build-tokens.mjs --check   CI: fail if a generated file is stale or a contrast pair fails
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "design-system");
const tokens = JSON.parse(readFileSync(join(dir, "tokens.json"), "utf8"));
const check = process.argv.includes("--check");

// ------------------------------------------------------------------ contrast (WCAG 2.x relative luminance)
const lum = (hex) => {
  const n = parseInt(hex.slice(1), 16);
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
export const contrast = (a, b) => {
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};

const report = [];
let failures = 0;
for (const [theme, t] of Object.entries(tokens.theme)) {
  for (const [fg, bg, min] of tokens.contrast.pairs) {
    const ratio = contrast(t[fg], t[bg]);
    const ok = ratio >= min;
    if (!ok) failures++;
    report.push({ theme, fg, bg, min, ratio: Math.round(ratio * 100) / 100, ok });
  }
}

// ------------------------------------------------------------------ CSS
const decl = (obj, prefix) => Object.entries(obj).filter(([k]) => !k.startsWith("$"))
  .map(([k, v]) => `  --${prefix}${k}: ${v};`).join("\n");
const themeDecl = (t) => Object.entries(t).map(([k, v]) => `  --color-${k}: ${v};`).join("\n");
const css = `/* GENERATED by scripts/build-tokens.mjs from tokens.json. Do not edit by hand. */
:root {
${decl(tokens.space, "space-")}
${decl(tokens.radius, "radius-")}
${decl(tokens.font, "font-")}
${decl(tokens.motion, "motion-")}
${themeDecl(tokens.theme.dark)}
  color-scheme: dark;
}
:root[data-theme="light"] {
${themeDecl(tokens.theme.light)}
  color-scheme: light;
}
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
${themeDecl(tokens.theme.light).replace(/^/gm, "  ")}
    color-scheme: light;
  }
}
`;

// ------------------------------------------------------------------ TS
const ts = `// GENERATED by scripts/build-tokens.mjs from tokens.json. Do not edit by hand.
export const themes = ${JSON.stringify(tokens.theme, null, 2)} as const;
export type ColorToken = keyof typeof themes.dark;
export const colorTokens = Object.keys(themes.dark) as ColorToken[];
export const contrastReport = ${JSON.stringify(report, null, 2)} as const;
/** CSS reference for a color token: var(--color-<name>) */
export const color = (t: ColorToken) => \`var(--color-\${t})\`;
`;

const outputs = { "tokens.css": css, "tokens.ts": ts };
let stale = [];
for (const [name, body] of Object.entries(outputs)) {
  const p = join(dir, name);
  if (check) {
    if (!existsSync(p) || readFileSync(p, "utf8").replace(/\r\n/g, "\n") !== body) stale.push(name);
  } else {
    writeFileSync(p, body);
  }
}

for (const r of report.filter((r) => !r.ok)) {
  console.error(`contrast FAIL [${r.theme}] ${r.fg} on ${r.bg}: ${r.ratio} < ${r.min}`);
}
console.log(`contrast: ${report.length - failures}/${report.length} pairs pass across ${Object.keys(tokens.theme).length} themes`);
if (stale.length) console.error(`stale generated files (run npm run tokens): ${stale.join(", ")}`);
if (failures || stale.length) process.exit(1);
